from lib import *
S = SS('s1')
steps = [
    step("一个只有两个请求的爬虫,在每一层都挂上钩子:start() → 下载器中间件 process_request → 下载 → process_response → 爬虫中间件 process_spider_input → 回调 → process_spider_output → item 进 pipeline、Request 回到调度器(request_scheduled)。共 29 个事件,几乎都落在同一毫秒到两毫秒里(服务器是本机回环)。注意两个顺序:request_reached_downloader 在下载器中间件 process_request 之后(第 6、7 行),response_received 在 process_response 之后(第 9、10 行);回调产出的 dict 先过爬虫中间件、再进 pipeline(第 13~15 行),产出的 Request 要等到第 16 行才发 request_scheduled,和 item 的处理是交错的,不是“先处理完 item 再调度 Request”。最后一个响应处理完,engine 发 spider_idle(第 28 行)然后关闭。", t=tl(S(1)), mark=lidx(S(1), '下载器中间件 process_request            /', 'signal:request_reached_downloader /', 'signal:request_scheduled          next'), done=lidx(S(1), 'spider.start()', 'callback parse    ', 'pipeline process_item             {\'page\': \'home\'}', 'signal:spider_idle'), kv=KV([['出发', 'spider.start() 产出 Request → 调度器'], ['下载前后', '下载器中间件 → 下载 → 下载器中间件'], ['回调前后', '爬虫中间件 input → 回调 → output'], ['item', '进 pipeline,发 item_scraped'], ['结束', '没有待办 → spider_idle → spider_closed']], ['出发'])),
    step("调度器出队顺序:默认是后进先出。树状站点 / → /a, /b,服务器收到的顺序是 / /b /a /b2 /a2 /a1 /b1,不是严格的深度优先:/b 下载完后下载器就空了,引擎马上取下一个请求 /a(这时 b 的回调还没跑),所以 /a 排在 /b2 之前。交错记录能看出来:开始下载b、开始下载a、回调开始b……。只设 DEPTH_PRIORITY=1 的结果和默认完全一样;只把磁盘/内存队列换成 FIFO 就变成广度优先:/ /a /b /a1 /a2 /b1 /b2;再加上 DEPTH_PRIORITY=1 结果不变。", t=tl(S(2)), mark=lidx(S(2), '默认:服务器收到', '开始下载b  开始下载a', '只换成 FIFO'), done=lidx(S(2), '只设 DEPTH_PRIORITY=1', 'DEPTH_PRIORITY=1 + FIFO'), kv=KV([['默认', '/ /b /a /b2 /a2 /a1 /b1'], ['只设 DEPTH_PRIORITY=1', '与默认相同'], ['FIFO 队列', '/ /a /b /a1 /a2 /b1 /b2(广度优先)'], ['原因', '下载器一空就取下一个,不等回调']], ['默认'])),
    step("并发上限直接决定引擎同时放出多少个请求。25 个请求(1 个起始页 + 24 个子页),子页每个服务器端延迟 0.3 s:CONCURRENT_REQUESTS=1 时总耗时 7.34 s(理想值 24×0.3=7.20),=4 时 1.88 s(1.80),=8 时 0.94 s(0.90),=24 时 0.34 s(0.30)。服务器那边看到的同时处理峰值恰好等于设置值 1、4、8、24(实验里同时把 CONCURRENT_REQUESTS_PER_DOMAIN 也调成了同样的值;这个每域名限制在默认的 asyncio reactor 下其实拦不住一次性涌入的请求,见本系列「并发控制」那一篇)。", t=tl(S(3)), mark=lidx(S(3), '                    1 ', '                   24 '), done=lidx(S(3), '                    4 ', '                    8 '), b=bars([['N=1', 7.34, '7.34 s'], ['N=4', 1.88, '1.88 s'], ['N=8', 0.94, '0.94 s'], ['N=24', 0.34, '0.34 s']], 7.34, mark=[3], done=[0, 1, 2]), kv=KV([['N=1', '7.34 s,峰值 1'], ['N=4', '1.88 s,峰值 4'], ['N=24', '0.34 s,峰值 24'], ['理想值', '24 × 0.3 / N']], ['N=24'])),
    step("回调返回的东西,引擎按类型分流:Request 进调度器(服务器多收到 /y);dict 当成 item(item_scraped_count=1);什么都不返回(None)不产生任何东西;列表 [dict, Request] 两样都处理(两个 item 里有一个来自第二个页面 /y 的回调,它又返回了同样的列表);更值得注意的是,字符串 'abc' 和整数 42 也被当成 item(item_scraped_count=1,日志里 Scraped from 后面是 'abc' 和 42),没有任何 ERROR,spider_exceptions/count 都是 0——没有 pipeline 检查类型时,引擎不会拒绝非法 item。", t=tl(S(4)), mark=lidx(S(4), "return 一个字符串", "yield 一个整数"), done=lidx(S(4), 'yield 一个 dict', 'yield 一个 Request', 'return None', 'return 一个列表'), kv=KV([['Request', '进调度器'], ['其它非 None 对象', '当 item(含 str、int)'], ['None', '什么都不发生'], ['spider_exceptions', '这些情形全是 0']], ['其它非 None 对象'])),
    step("“跑完了”由引擎判断:下载器没有活动请求、scraper 空闲、start() 已耗尽、调度器没有待办,就发 spider_idle;处理函数抛 DontCloseSpider 引擎就不关。被拒绝关闭后,下次检查靠 5 秒一次的心跳(源码里 _SLOT_HEARTBEAT_INTERVAL = 5.0):第 1、2 次 spider_idle 相隔 4997 ms,第 3、4 次相隔 4995 ms。如果在 idle 里用 crawler.engine.crawl() 塞一个新请求,马上被处理:第 2 次 idle 在 5151 ms,/late 的回调在 5155 ms,第 3 次 idle 在 5156 ms,只隔 5 ms。scheduler_empty 信号在这期间累计触发 4、5、8、9 次,反映引擎一次次去调度器取请求但取不到。最后因为第 4 次 idle 不再抛 DontCloseSpider,spider 以 finished 关闭。", t=tl(S(5)), mark=lidx(S(5), 'spider_idle  n=2', 'spider_idle  n=4', '相邻两次'), done=lidx(S(5), 'spider_idle  n=1', '塞进一个新请求', 'late 回调'), kv=KV([['idle 条件', '下载器、scraper、start()、调度器都空'], ['DontCloseSpider', '拒绝关闭,5 秒后再查'], ['心跳间隔', '约 4995~4997 ms'], ['engine.crawl()', '在 idle 里塞请求,5 ms 内被处理']], ['心跳间隔'])),
]
A = mkarts('s1', 1, 'Scrapy,引擎,调度器,下载器,信号,spider_idle,真实验证,动画演示',
    '在 Scrapy 2.19 上给引擎的每一层挂钩子,记录一个请求的完整路径(29 个事件);默认队列是后进先出、不是严格深度优先;CONCURRENT_REQUESTS 从 1 到 24 总耗时 7.34 s 降到 0.34 s;回调返回字符串和整数也被当成 item;DontCloseSpider 之后 spider_idle 每约 5 秒重复一次。',
    '一个 Request 从 spider 出发,经过调度器、下载器、爬虫中间件、回调、pipeline 再回来,每一站到底按什么顺序、由谁推着走?这篇给 Scrapy 2.19 的每一层挂上钩子,把一次抓取的完整轨迹按毫秒打出来,再用实验验证调度顺序、并发上限和“跑完”的判断。',
    [('29 个', '两个请求的抓取里,各层钩子与信号一共触发的事件数'), ('7.34 → 0.34 s', 'CONCURRENT_REQUESTS 从 1 增到 24,25 个请求(每个 0.3 s)的总耗时'), ('≈5 s', 'DontCloseSpider 之后 spider_idle 重复触发的间隔(4997 / 4995 ms)')],
    [('一个请求的完整路径', '<p>引擎(<code>scrapy/core/engine.py</code>)把 <code>spider.start()</code> 产出的 Request 交给调度器,再从调度器取出交给下载器。下载器中间件、爬虫中间件、回调、pipeline 各自在固定的位置被调用:<code>process_request → 下载 → process_response → process_spider_input → 回调 → process_spider_output →</code> item 去 pipeline、Request 回调度器。上面的记录能验证每一步的先后,也能看到信号 <code>request_reached_downloader</code>、<code>response_received</code>、<code>item_scraped</code> 在哪个点发出。</p>'),
     ('调度器的出队顺序', '<p>默认队列是后进先出,但因为“下载”和“回调”是流水线(下载器一空出来引擎就去取下一个请求,不等上一个回调跑完),并发为 1 时也不是严格的深度优先。要广度优先,换成 FIFO 的内存队列和磁盘队列;只改 <code>DEPTH_PRIORITY</code> 在这个例子里没有改变顺序。</p>'),
     ('并发上限', '<p>引擎只要下载器还有空位(<code>needs_backout()</code> 为假)就继续从调度器取请求。<code>CONCURRENT_REQUESTS</code> 就是这个空位数。实测总耗时几乎等于 24×0.3/N 再加几十毫秒。(同一域名还有一个 <code>CONCURRENT_REQUESTS_PER_DOMAIN</code>,在默认的 asyncio reactor 下的实际效果见「并发控制」那一篇。)</p>'),
     ('回调返回什么', '<p>引擎只区分“是不是 Request”:是就调度,不是就当成 item 交给 pipeline。它自己不检查 item 的类型,所以字符串和整数也会被计入 <code>item_scraped_count</code>;类型检查是 pipeline 或导出器的事。</p>'),
     ('什么时候算跑完', '<p>下载器、scraper、<code>start()</code>、调度器全空才算 idle。处理 <code>spider_idle</code> 的函数可以抛 <code>DontCloseSpider</code> 让爬虫继续活着(常见于从外部队列取任务),这种情况下引擎靠 5 秒一次的心跳重新检查;在 idle 里用 <code>engine.crawl()</code> 塞新请求则会立刻被处理。</p>')],
    steps,
    [ENV_Y + '。第一节:自己写的最小 spider,挂了扩展(信号)、下载器中间件、爬虫中间件、pipeline;第二节:树状站点,CONCURRENT_REQUESTS=1;第三节:服务器端 time.sleep(0.3) 制造延迟,峰值是服务器端同时在处理的请求数;第五节:signals.spider_idle + DontCloseSpider',
     '没有验证:多个域名同时抓取时的调度顺序;优先级(Request.priority)与深度的组合(见后面的文章);磁盘队列(JOBDIR)下的顺序;网络延迟不是 0 时下载器与回调的交错程度;scheduler_empty 在真实负载下的触发频率;异步回调(async def)对引擎循环的影响(见后面的文章);Scrapy 2.19 之外的版本'],
    '请求的路径')
